{"command": "# Try the JSON-LD / structured data from RaceDayQuads product pages (Shopify)
get_shopify_json() {
  curl -sL -m 10 -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36" "$1" 2>&1 | grep -oP '"price":[0-9.]+|"price":"[0-9.]+"|"availability":"[^"]*"' | head -3
}

# BAT04 - Lumenier NAV 12000mAh 4S Amprius
echo "=== BAT04 RDQ ==="
get_shopify_json "https://www.racedayquads.com/products/lumenier-nav-12000mah-4s-21700-amprius-lithium-ion-battery-xt60"

# Instead let me just regex the full page for the price variable
curl -sL -m 10 -A "Mozilla/5.0" "https://www.racedayquads.com/products/lumenier-nav-12000mah-4s-21700-amprius-lithium-ion-battery-xt60" 2>&1 | grep -oP '"price":\s*[0-9.]+|final_price":\s*[0-9.]+' | head -3", "timeout": 30}
